func handler(req map[string]interface{}) map[string]interface{} {
	bodyStr, _ := req["body"].(string)
	var body map[string]interface{}
	json.Unmarshal([]byte(bodyStr), &body)

	input, _ := body["input"].(string)
	if input == "" {
		return map[string]interface{}{"error": "input field required"}
	}

	return map[string]interface{}{
		"input":         input,
		"sha256":        SHA256Hash(input),
		"md5":           MD5Hash(input),
		"base64":        Base64Encode(input),
		"url_encoded":   URLEncode(input),
		"length":        len(input),
		"byte_length":   len([]byte(input)),
	}
}
